<script lang="ts">
import {tick} from 'svelte';
import Icon from './Icon.svelte';
let {label,icon='text',value=$bindable(''),options,onchange}: {label:string;icon?:string|null;value?:string;options:{value:string;label:string}[];onchange?:(value:string)=>void}=$props();
let prefix='';let prefixAt=0;let open=$state(false);let active=$state(0);let root=$state<HTMLDivElement>();let list=$state<HTMLDivElement>();let position=$state({left:0,top:0,width:0,maxHeight:220});const uid=$props.id();
async function show(){prefix='';prefixAt=0;const rect=root?.getBoundingClientRect();if(!rect)return;const below=window.innerHeight-rect.bottom-12;const above=rect.top-12;const height=Math.min(220,Math.max(below,above));position={left:rect.left,top:below>=140||below>=above?rect.bottom+6:Math.max(8,rect.top-height-6),width:rect.width,maxHeight:height};active=Math.max(0,options.findIndex(v=>v.value===value));open=true;await tick();if(typeof list?.showPopover==='function')list.showPopover();list?.focus();list?.querySelector(`[data-index="${active}"]`)?.scrollIntoView({block:'nearest'});}
function choose(index:number){if(options[index]){value=options[index].value;onchange?.(value);}open=false;root?.querySelector('button')?.focus();}
function key(event:KeyboardEvent){if(event.key==='Escape'){event.preventDefault();event.stopPropagation();open=false;root?.querySelector('button')?.focus();}else if(event.key==='ArrowDown'||event.key==='ArrowUp'){event.preventDefault();active=Math.max(0,Math.min(options.length-1,active+(event.key==='ArrowDown'?1:-1)));list?.querySelector(`[data-index="${active}"]`)?.scrollIntoView({block:'nearest'});}else if(event.key==='Enter'){event.preventDefault();choose(active);}else if(event.key==='Tab'){open=false;}else if(event.key.length===1&&!event.ctrlKey&&!event.metaKey&&!event.altKey){event.preventDefault();const now=performance.now();prefix=now-prefixAt<750?prefix+event.key.toLocaleLowerCase():event.key.toLocaleLowerCase();prefixAt=now;let next=options.findIndex(o=>o.label.toLocaleLowerCase().startsWith(prefix));if(next<0){prefix=event.key.toLocaleLowerCase();next=options.findIndex((o,index)=>index>active&&o.label.toLocaleLowerCase().startsWith(prefix));if(next<0)next=options.findIndex(o=>o.label.toLocaleLowerCase().startsWith(prefix));}if(next>=0){active=next;list?.querySelector(`[data-index="${active}"]`)?.scrollIntoView({block:'nearest'});}}}
</script>
<svelte:window onpointerdown={event=>{if(open&&!root?.contains(event.target as Node))open=false;}}/>
<div class="choice-field" bind:this={root}><button class="profile-field" type="button" aria-expanded={open} aria-haspopup="listbox" aria-label={`${label}: ${options.find(o=>o.value===value)?.label??'—'}`} onclick={()=>{if(open)open=false;else void show();}} onkeydown={event=>{if(event.key==='ArrowDown'){event.preventDefault();void show();}}}>{#if icon}<Icon name={icon}/>{/if}<span><small>{label}</small><b>{options.find(o=>o.value===value)?.label??'—'}</b></span><Icon name="chevron-down" size={16}/></button>{#if open}<div class="popup choice-options" popover="manual" style:left={`${position.left}px`} style:top={`${position.top}px`} style:width={`${position.width}px`} style:max-height={`${position.maxHeight}px`} role="listbox" aria-label={label} aria-activedescendant={`${uid}-${active}`} tabindex="-1" bind:this={list} onkeydown={key}>{#each options as option,index}<button type="button" id={`${uid}-${index}`} role="option" aria-selected={value===option.value} class:highlight={active===index} data-index={index} tabindex="-1" onpointermove={()=>active=index} onclick={()=>choose(index)}>{option.label}</button>{/each}</div>{/if}</div>
